126				const selection = coalesce(list.getSelection().filter((item): item is ExplorerItem => item instanceof ExplorerItem));
127				const resources = getMultiSelectedResourcesForExplorer(resource, focus, selection);
128				if (resources.length) {
129					return resources;
130				}
131			}
132	
133			// Open editors view
134			if (list instanceof List) {
135				const selection = coalesce(list.getSelectedElements().filter(s => s instanceof OpenEditor).map((oe: OpenEditor) => oe.getResource()));
136				const focusedElements = list.getFocusedElements();
137				const focus = focusedElements.length ? focusedElements[0] : undefined;
138				let mainUriStr: string | undefined = undefined;
139				if (URI.isUri(resource)) {
140					mainUriStr = resource.toString();
141				} else if (focus instanceof OpenEditor) {
142					const focusedResource = focus.getResource();
143					mainUriStr = focusedResource ? focusedResource.toString() : undefined;
144				}
145				// We only respect the selection if it contains the main element.
146				if (selection.some(s => s.toString() === mainUriStr)) {
147					return selection;
148				}
149			}
150		}
151	
152		const result = getResourceForCommand(resource, listService, editorService);
153		return !!result ? [result] : [];
